sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float position;
uniform float width;
uniform float softness;
uniform float intensity;
layout(color) uniform half4 color;
uniform float show;
uniform float threshold;
uniform float radius;
uniform float feather;
uniform float smoothing;
layout(color) uniform half4 tint;
uniform float blend;
uniform float fill;
uniform float alpha;
uniform float style;
uniform float4 screen;
half4 classic(float2 coord) {
    half4 src = image.eval(coord);
    half4 soft = blurred.eval(coord);
    float lum = src.a > 0.0 ? dot(float3(src.rgb) / float(src.a), float3(0.2126, 0.7152, 0.0722)) : 0.0;
    float half_band = max(width, 0.0) * 0.5;
    float m = 1.0 - smoothstep(half_band, half_band + max(softness, 0.001), abs(lum - position));
    m *= float(src.a);
    float3 glowRgb = float3(soft.rgb) * float3(color.rgb) * max(intensity, 0.0) * m;
    half4 base = show > 0.5 ? src * half(m) : src;
    half4 mixed = half4(mix(base.rgb, soft.rgb, half(m)), base.a);
    return half4(min(mixed.rgb + half3(glowRgb), mixed.a), mixed.a);
}
half4 standard(float2 coord) {
    half4 src = image.eval(coord);
    float2 q = (coord - screen.xy) * 0.5 - 0.5;
    float2 i0 = floor(q);
    float2 f = q - i0;
    float2 c0 = 2.0 * i0 + 1.0 + screen.xy;
    half4 sm = mix(mix(blurred.eval(c0), blurred.eval(c0 + float2(2.0, 0.0)), half(f.x)),
                   mix(blurred.eval(c0 + float2(0.0, 2.0)), blurred.eval(c0 + float2(2.0, 2.0)), half(f.x)), half(f.y));
    float3 c = sm.a > 0.0 ? float3(sm.rgb) / float(sm.a) : float3(0.0);
    float l = dot(c, float3(0.2126, 0.7152, 0.0722));
    float mid = 1.1 * threshold - 0.05;
    float s0 = max(0.412 * radius * pow(max(mid, 0.0) / 0.5, 0.74), 0.0001);
    float t = (l - mid - 0.31 * radius * radius) / s0;
    float e = abs(l - mid) <= 0.5 * radius + 0.0015 ? 2.0 * pow(exp(-t * t), 0.5 * max(feather, 0.0)) * float(src.a) : 0.0;
    float3 k = float3(tint.rgb) / max(float(tint.a), 0.0001);
    float3 cl = pow(clamp(c, 0.0, 1.0), float3(1.5));
    float3 own = cl / max(dot(cl, float3(0.2126, 0.7152, 0.0722)), 0.0001);
    float3 hue = mix(own, k, clamp(blend, 0.0, 1.0));
    float ea = e * max(alpha, 0.0);
    float over = max(ea - 1.0, 0.0) / 0.85;
    float3 lit = min(float3(1.0), min(float3(1.0), ea * hue) + over * over * (1.0 - min(float3(1.0), ea * hue)));
    float3 b = e > 0.0 ? clamp(c, 0.0, 1.0) * float(src.a) : float3(src.rgb) * clamp(fill, 0.0, 1.0);
    float3 rgb = 1.0 - (1.0 - b) * (1.0 - lit * float(src.a));
    return half4(half3(min(rgb, float3(src.a))), src.a);
}
half4 main(float2 coord) {
    return style > 0.5 ? standard(coord) : classic(coord);
}
